include("apis/api_TrendsApi.jl")
include("apis/api_UserAccountApi.jl")

"""
Register handlers for all APIs in this module in the supplied `Router` instance.

Paramerets:
- `router`: Router to register handlers in
- `impl`: module that implements the server methods

Optional parameters:
- `path_prefix`: prefix to be applied to all paths
- `optional_middlewares`: Register one or more optional middlewares to be applied to all requests.

Optional middlewares can be one or more of:
    - `init`: called before the request is processed
    - `pre_validation`: called after the request is parsed but before validation
    - `pre_invoke`: called after validation but before the handler is invoked
    - `post_invoke`: called after the handler is invoked but before the response is sent

The order in which middlewares are invoked are:
`init |> read |> pre_validation |> validate |> pre_invoke |> invoke |> post_invoke`
"""
function register(router::HTTP.Router, impl; path_prefix::String="", optional_middlewares...)
    registerAdAccountsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerAdGroupsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerAdsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerAdvancedAuctionApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerAudienceInsightsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerAudienceSharingApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerAudiencesApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerBillingApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerBoardsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerBulkApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerBusinessAccessAssetsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerBusinessAccessInviteApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerBusinessAccessRelationshipsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerCampaignsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerCatalogFeedsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerCatalogItemsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerCatalogProductGroupsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerCatalogReportsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerCatalogSupplementalApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerCatalogsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerConversionDeletionRequestsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerConversionEqsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerConversionEventsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerConversionTagsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerConversionsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerCustomerListUploadsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerCustomerListsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerCustomerSegmentApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerIntegrationsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerKeywordsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerLabelsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerLeadAdsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerLeadFormsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerLeadsExportApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerMediaApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerMsotEventsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerNotificationApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerOauthApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerOrderLinesApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerPinsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerProductGroupPromotionsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerProductTagsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerPromotionsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerResourcesApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerSchedulesApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerSearchApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerTargetingTemplateApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerTermsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerTermsOfServiceApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerTrendsApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    registerUserAccountApi(router, impl; path_prefix=path_prefix, optional_middlewares...)
    return router
end

end # module APIServer
